window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b91176fad72afb11"]={"versions": [{"id": "FIG-b91176fad72afb11", "releases": ["R2.1.20", "R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Prozess-/Aktivitätsdiagramm mit Swimlanes (Rollen- und Verantwortlichkeitsaufteilung nach BPMN/UML-Aktivitätssemantik).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des standardisierten Prüf- und Zertifizierungsablaufs nach <strong>Pfad B (Self Conformance Test)</strong> gemäß <code>AUTOSAR_DS_CT_Path_A-C</code> (Releases R2.1.20, R3.0.7).</li>\n<li><strong>Kontext im Gesamtsystem:</strong> Regelt das herstellerinterne Konformitätsverfahren für AUTOSAR-Basissoftware (BSW), RTE und System-Services zur Verifikation der Konformität gegenüber den normativen AUTOSAR-Spezifikationen (SWS) ohne direkte Auditierung durch das AUTOSAR-Konsortium.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Domänen (Swimlanes):</strong></li>\n<li><code>First party Conformance Test Agency</code>: Der BSW-Hersteller, Tier-1-Zulieferer oder OEM, der gleichzeitig Produktentwickler und interne Testinstanz ist.</li>\n<li><code>CTA *<em>)</code> (</em>Conformance Test Agency*): Eine durch AUTOSAR akkreditierte externe Prüfstelle aus Pfad A oder C, die hier ausschließlich als lizenzierter Distributor der offiziellen Testsuite fungiert.</li>\n<li><code>AUTOSAR</code>: Dachorganisation/Konsortium. Im Pfad B rein passiv dargestellt (keine Interaktionskanten), da keine zentrale Zertifikatsausstellung oder Berichtsprüfung erfolgt.</li>\n<li><strong>Prozessknoten & Artefakte:</strong></li>\n<li><code>Product development</code>: Entwicklung des AUTOSAR-Produkts (BSW-Treiber, Kommunikationsstacks, OS, RTE).</li>\n<li><code>Purchase CTS</code>: Kommerzieller/formeller Beschaffungsschritt der Testwerkzeuge.</li>\n<li><code>Conformance Test Suite (CTS)</code>: Offiziell validierte, normierte Testsuite (Testfälle, Test-Harness, Skripte, z. B. TTCN-3/C-Testsuites).</li>\n<li><code>Test execution (perform test against product)</code>: Ausführung der Testsuite gegen die Ziel-Softwarekomponente/Target-Hardware (DUT/SUT).</li>\n<li><code>result (Verzweigung/Decision)</code>: Boolescher Gate-Keeper (<code>OK</code> vs. <code>not OK</code>).</li>\n<li><code>Create test report</code>: Generierung des lückenlosen Konformitäts-Testprotokolls.</li>\n<li><code>Self conformance declaration</code>: Rechtsverbindliche Konformitäts-Selbsterklärung des Herstellers.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Tool-Beschaffung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parallel oder nachgelagert zur initialen Phase <code>Product development</code> wird die offizielle <code>Conformance Test Suite (CTS)</code> von einer akkreditierten <code>CTA</code> bezogen (<code>Purchase CTS</code> $\\rightarrow$ Bereitstellung <code>CTS</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Testdurchführung (Closed Loop):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die BSW-Implementierung und die bezogene CTS werden in <code>Test execution (perform test against product)</code> zusammengeführt.</li>\n<li>Bewertung des Testergebnisses an der Verzweigung <code>result</code>:</li>\n<li><strong>Pfad <code>not OK</code> (Fehlerschlag):</strong> Rücksprung zu <code>Product development</code>. Anpassen von BSW-Code, Konfiguration oder Stubs.</li>\n<li>*<em>Iterationsschleife <code>1+ cycle</em>)</code>:** Re-Integration und erneute Testausführung, bis alle normativen Testfälle fehlerfrei durchlaufen sind.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss & Deklaration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad <code>OK</code>:</strong> Nach erfolgreichem Durchlauf aller geforderten Testfälle wird <code>Create test report</code> getriggert.</li>\n<li>Abschließende Generierung der <code>Self conformance declaration</code>.</li>\n<li><strong>Terminierung:</strong> Der Prozess endet herstellerintern; es findet kein Rückkanal oder Reporting an die Swimlane <code>AUTOSAR</code> statt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Prüfumfang & ICC-Klassen:</strong></li>\n<li>Relevanz für BSW-Stack-Entwickler (z. B. Can, Lin, Com, PduR, Os, NvM, MemIf): Die CTS testet strikt gegen die definierten API-Signaturen, das geforderte Zustands- und Fehlerechoverhalten (Det/Dem) sowie Busprotokolle.</li>\n<li>Bei proprietärer Modularisierung unterhalb von ICC1/ICC2 sind nur die extern sichtbaren Schnittstellen gegen die CTS prüfbar; bei ICC3 muss jedes einzelne BSW-Modul die normativen Modultests bestehen.</li>\n<li><strong>Testumgebung & Hardware-Abhängigkeiten:</strong></li>\n<li>Für <code>Test execution</code> müssen Entwickler Test-Stubs, Upper-Tester und Lower-Tester implementieren oder konfigurieren, um stimulusgesteuerte Testfallausführungen der CTS auf dem Ziel-Mikrocontroller bzw. Simulator zu ermöglichen.</li>\n<li><strong>Haftung & Dokumentationspflicht:</strong></li>\n<li>Da AUTOSAR im Pfad B kein offizielles Konformitätszertifikat ausstellt, ist der intern erstellte Testbericht (<code>Create test report</code>) zwingender Bestandteil der OEM-Freigabedokumentation.</li>\n<li>Abweichungen, Waivers oder unvollständige Konfigurationsszenarien müssen exakt im Report dokumentiert sein, um die Gültigkeit der <code>Self conformance declaration</code> rechtssicher zu gewährleisten.</li>\n</ul>"}, {"id": "FIG-cb9c660ca26686b1", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Prozess-/Aktivitätsdiagramm mit Swimlanes (Rollen- und Verantwortlichkeitsaufteilung nach BPMN/UML-Aktivitätssemantik).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des standardisierten Prüf- und Zertifizierungsablaufs nach <strong>Pfad B (Self Conformance Test)</strong> gemäß <code>AUTOSAR_DS_CT_Path_A-C</code> (Releases R2.1.20, R3.0.7).</li>\n<li><strong>Kontext im Gesamtsystem:</strong> Regelt das herstellerinterne Konformitätsverfahren für AUTOSAR-Basissoftware (BSW), RTE und System-Services zur Verifikation der Konformität gegenüber den normativen AUTOSAR-Spezifikationen (SWS) ohne direkte Auditierung durch das AUTOSAR-Konsortium.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Domänen (Swimlanes):</strong></li>\n<li><code>First party Conformance Test Agency</code>: Der BSW-Hersteller, Tier-1-Zulieferer oder OEM, der gleichzeitig Produktentwickler und interne Testinstanz ist.</li>\n<li><code>CTA *<em>)</code> (</em>Conformance Test Agency*): Eine durch AUTOSAR akkreditierte externe Prüfstelle aus Pfad A oder C, die hier ausschließlich als lizenzierter Distributor der offiziellen Testsuite fungiert.</li>\n<li><code>AUTOSAR</code>: Dachorganisation/Konsortium. Im Pfad B rein passiv dargestellt (keine Interaktionskanten), da keine zentrale Zertifikatsausstellung oder Berichtsprüfung erfolgt.</li>\n<li><strong>Prozessknoten & Artefakte:</strong></li>\n<li><code>Product development</code>: Entwicklung des AUTOSAR-Produkts (BSW-Treiber, Kommunikationsstacks, OS, RTE).</li>\n<li><code>Purchase CTS</code>: Kommerzieller/formeller Beschaffungsschritt der Testwerkzeuge.</li>\n<li><code>Conformance Test Suite (CTS)</code>: Offiziell validierte, normierte Testsuite (Testfälle, Test-Harness, Skripte, z. B. TTCN-3/C-Testsuites).</li>\n<li><code>Test execution (perform test against product)</code>: Ausführung der Testsuite gegen die Ziel-Softwarekomponente/Target-Hardware (DUT/SUT).</li>\n<li><code>result (Verzweigung/Decision)</code>: Boolescher Gate-Keeper (<code>OK</code> vs. <code>not OK</code>).</li>\n<li><code>Create test report</code>: Generierung des lückenlosen Konformitäts-Testprotokolls.</li>\n<li><code>Self conformance declaration</code>: Rechtsverbindliche Konformitäts-Selbsterklärung des Herstellers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Tool-Beschaffung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parallel oder nachgelagert zur initialen Phase <code>Product development</code> wird die offizielle <code>Conformance Test Suite (CTS)</code> von einer akkreditierten <code>CTA</code> bezogen (<code>Purchase CTS</code> $\\rightarrow$ Bereitstellung <code>CTS</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Testdurchführung (Closed Loop):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die BSW-Implementierung und die bezogene CTS werden in <code>Test execution (perform test against product)</code> zusammengeführt.</li>\n<li>Bewertung des Testergebnisses an der Verzweigung <code>result</code>:</li>\n<li><strong>Pfad <code>not OK</code> (Fehlerschlag):</strong> Rücksprung zu <code>Product development</code>. Anpassen von BSW-Code, Konfiguration oder Stubs.</li>\n<li>*<em>Iterationsschleife <code>1+ cycle</em>)</code>:** Re-Integration und erneute Testausführung, bis alle normativen Testfälle fehlerfrei durchlaufen sind.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss & Deklaration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad <code>OK</code>:</strong> Nach erfolgreichem Durchlauf aller geforderten Testfälle wird <code>Create test report</code> getriggert.</li>\n<li>Abschließende Generierung der <code>Self conformance declaration</code>.</li>\n<li><strong>Terminierung:</strong> Der Prozess endet herstellerintern; es findet kein Rückkanal oder Reporting an die Swimlane <code>AUTOSAR</code> statt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Prüfumfang & ICC-Klassen:</strong></li>\n<li>Relevanz für BSW-Stack-Entwickler (z. B. Can, Lin, Com, PduR, Os, NvM, MemIf): Die CTS testet strikt gegen die definierten API-Signaturen, das geforderte Zustands- und Fehlerechoverhalten (Det/Dem) sowie Busprotokolle.</li>\n<li>Bei proprietärer Modularisierung unterhalb von ICC1/ICC2 sind nur die extern sichtbaren Schnittstellen gegen die CTS prüfbar; bei ICC3 muss jedes einzelne BSW-Modul die normativen Modultests bestehen.</li>\n<li><strong>Testumgebung & Hardware-Abhängigkeiten:</strong></li>\n<li>Für <code>Test execution</code> müssen Entwickler Test-Stubs, Upper-Tester und Lower-Tester implementieren oder konfigurieren, um stimulusgesteuerte Testfallausführungen der CTS auf dem Ziel-Mikrocontroller bzw. Simulator zu ermöglichen.</li>\n<li><strong>Haftung & Dokumentationspflicht:</strong></li>\n<li>Da AUTOSAR im Pfad B kein offizielles Konformitätszertifikat ausstellt, ist der intern erstellte Testbericht (<code>Create test report</code>) zwingender Bestandteil der OEM-Freigabedokumentation.</li>\n<li>Abweichungen, Waivers oder unvollständige Konfigurationsszenarien müssen exakt im Report dokumentiert sein, um die Gültigkeit der <code>Self conformance declaration</code> rechtssicher zu gewährleisten.</li>\n</ul>"}], "trans": [{"from": "FIG-b91176fad72afb11", "to": "FIG-cb9c660ca26686b1", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
